commands:
cd /home/runner/work/prflow/prflow
BRANCH=$(.prflow/vendor/prflow/scripts/branch-for-issue.py 1771 --title-file .prflow/tmp/devflow-issue-1771-title.txt) || { echo "BRANCH-FOR-ISSUE FAILED"; exit 1; }
echo "BRANCH=$BRANCH"
[ -n "$BRANCH" ] || { echo "EMPTY BRANCH"; exit 1; }
git checkout -b "$BRANCH" origin/main
